@Test
public void calculateChargebackAllocationMap() {
    Map<AllocationType, Money> result;
    MonetaryCurrency currency = mock(MonetaryCurrency.class);
    result = underTest.calculateChargebackAllocationMap(allocationMap(50.0, 100.0, 200.0, 12.0, currency), BigDecimal.valueOf(50.0), List.of(PRINCIPAL, INTEREST, FEE, PENALTY), currency);
    verify(allocationMap(50.0, 0, 0, 0, currency), result);
    result = underTest.calculateChargebackAllocationMap(allocationMap(40.0, 100.0, 200.0, 12.0, currency), BigDecimal.valueOf(50.0), List.of(PRINCIPAL, INTEREST, FEE, PENALTY), currency);
    verify(allocationMap(40.0, 10, 0, 0, currency), result);
    result = underTest.calculateChargebackAllocationMap(allocationMap(40.0, 100.0, 200.0, 12.0, currency), BigDecimal.valueOf(50.0), List.of(PRINCIPAL, FEE, PENALTY, INTEREST), currency);
    verify(allocationMap(40.0, 0, 10, 0, currency), result);
    result = underTest.calculateChargebackAllocationMap(allocationMap(40.0, 100.0, 200.0, 12.0, currency), BigDecimal.valueOf(340.0), List.of(PRINCIPAL, FEE, PENALTY, INTEREST), currency);
    verify(allocationMap(40.0, 88.0, 200.0, 12.0, currency), result);
    result = underTest.calculateChargebackAllocationMap(allocationMap(40.0, 100.0, 200.0, 12.0, currency), BigDecimal.valueOf(352.0), List.of(PRINCIPAL, FEE, PENALTY, INTEREST), currency);
    verify(allocationMap(40.0, 100.0, 200.0, 12.0, currency), result);
}

