    when(loanDelinquencyDomainService.getLoanDelinquencyData(loanForProcessing, effectiveDelinquencyList)).thenReturn(loanDelinquencyData);
    when(loanInstallmentDelinquencyTagRepository.findByLoanAndInstallment(loanForProcessing, repaymentScheduleInstallments.get(0))).thenReturn(Optional.empty());
    // when
    underTest.applyDelinquencyTagToLoan(loanScheduleDelinquencyData, effectiveDelinquencyList);
    // then
    InOrder inOrder = inOrder(delinquencyWritePlatformServiceHelper);
    inOrder.verify(delinquencyWritePlatformServiceHelper).applyDelinquencyForLoan(eq(loanForProcessing), eq(delinquencyBucket), anyLong());
    inOrder.verify(delinquencyWritePlatformServiceHelper).applyDelinquencyForLoanInstallments(eq(loanForProcessing), eq(delinquencyBucket), eq(installmentsCollection));
